interface ILido {
function submit(address) external payable;
}

interface IBalancer {
function flashLoan(
address recipient,
address[] calldata tokens,
uint256[] calldata amounts,
bytes calldata userData
) external;
}

interface IBalancerFee{
function getFlashLoanFeePercentage() external view returns (uint256);
}

interface ICurve{
